            end_j = min(j + tile_cols, N)
            num_rows = end_i - i
            num_cols = end_j - j

            # Pass 1: Compute mean for each row in this tile
            mu = np.zeros(num_rows, dtype=np.float64)
            for col in range(j, end_j):
                for row in range(i, end_i):
                    mu[row - i] += x[row, col]

            mu /= N

            # Pass 2: Compute variance for each row in this tile
            ss = np.zeros(num_rows, dtype=np.float64)
            for col in range(j, end_j):
                for row in range(i, end_i):
                    d = x[row, col] - mu[row - i]
                    ss[row - i] += d * d

            rinv = 1.0 / np.sqrt(ss / N + eps)

            # Pass 3: Compute output
            for col in range(j, end_j):
                for row in range(i, end_i):
                    y[row, col] = (x[row, col] - mu[row - i]) * rinv[row - i]

    return y
